diff --git a/src/qbe_loop_unswitch_test.zig b/src/qbe_loop_unswitch_test.zig
index 257354a7..770f51b6 100644
--- a/src/qbe_loop_unswitch_test.zig
+++ b/src/qbe_loop_unswitch_test.zig
@@ -206,6 +206,7 @@ test "invariant loop dispatch specializes every literal and preserves checked ca
     const il = try named(fast.value, "main");
     try t.expect(std.mem.indexOf(u8, il, "QBE-LOOP-UNSWITCH-1") != null);
     try t.expect(std.mem.indexOf(u8, il, "literals=3") != null);
+    try t.expectEqual(@as(usize, 3), std.mem.count(u8, il, " =l ceql %usk"));
     try t.expect(std.mem.indexOf(u8, il, "_original_") != null);
     try t.expect(std.mem.indexOf(u8, il, "myl_qbe_fail_normalized_index_bounds") != null);
     try t.expect(std.mem.indexOf(u8, il, "myl_qbe_fail_division") != null);
diff --git a/src/qbe_loop_unswitch_text.zig b/src/qbe_loop_unswitch_text.zig
index 3a515ad3..4bd8357a 100644
--- a/src/qbe_loop_unswitch_text.zig
+++ b/src/qbe_loop_unswitch_text.zig
@@ -38,7 +38,16 @@ pub fn rewrite(a: std.mem.Allocator, input: []const u8, certificate: proof.Certi
         }
         const function_room = @max(4096, input.len / 2);
         const allowed = @min(max_added, @min(function_room, body.len * 2));
-        if (copies.writer.end > allowed) return a.dupe(u8, input);
+        if (copies.writer.end > allowed) {
+            const commented = try std.mem.replaceOwned(u8, a, input, "\n", "\n# ");
+            defer a.free(commented);
+            return std.fmt.allocPrint(a, "# unswitch-budget head={d} back={d} slot={d} conditions={d} values={d} value={d} copied={d} allowed={d} region={d} input={d}\n" ++
+                "# UNSWITCH-INPUT-BEGIN\n# {s}\n# UNSWITCH-INPUT-END\n{s}", .{
+                certificate.head, certificate.back,  certificate.slot, certificate.conditions.len, certificate.values.len,
+                value,            copies.writer.end, allowed,          body.len,                   input.len,
+                commented,        input,
+            });
+        }
     }
     var out: std.Io.Writer.Allocating = .init(a);
     errdefer out.deinit();
